{{-- Wiersz x-admiro::attributes-editor: uchwyt przeciągania, grupa, nazwa, wartość i „Usuń”. index: int|string (numer wiersza albo `__INDEX__` w szablonie); attribute: ?Attributes\CustomAttribute; blank: bool (pusty wiersz na nowy atrybut bez skryptu — skrypt go usuwa). Zmienne $field (nazwa pola sekcji), $idPrefix, $nameMax, $valueMax z edytora. --}}
<li class="ss-attributes__row" data-ss-attributes-row @if ($blank) data-ss-attributes-blank @endif>
    <span class="ss-attributes__handle" title="{{ text('layout.attributes.move') }}" tabindex="0" role="button" hidden data-ss-attributes-handle><x-admiro::icon name="grip" class="ss-icon" /><span class="ss-sr-only">{{ text('layout.attributes.move') }}</span></span>
    <x-admiro::input :id="$idPrefix . '-' . $index . '-group'" :name="$field . '[' . $index . '][group]'" :label="text('layout.attributes.group')" :value="$attribute?->group" :maxlength="$nameMax" field-class="ss-attributes__field" />
    <x-admiro::input :id="$idPrefix . '-' . $index . '-name'" :name="$field . '[' . $index . '][name]'" :label="text('layout.attributes.name')" :value="$attribute?->name" :maxlength="$nameMax" field-class="ss-attributes__field" />
    <x-admiro::input :id="$idPrefix . '-' . $index . '-value'" :name="$field . '[' . $index . '][value]'" :label="text('layout.attributes.value')" :value="$attribute?->value" :maxlength="$valueMax" field-class="ss-attributes__field ss-attributes__field--value" />
    <button class="ss-icon-button ss-attributes__remove" type="button" title="{{ text('layout.attributes.remove') }}" hidden data-ss-attributes-remove><x-admiro::icon name="trash" class="ss-icon-button__icon" /><span class="ss-sr-only">{{ text('layout.attributes.remove') }}</span></button>
</li>
